// Lint and bundle contracts/openapi.yaml, and generate the TypeScript path types from the bundle.
//   node scripts/contracts-openapi.mjs           lint, then write contracts/openapi.bundled.json and
//                                                packages/core/src/generated/api-paths.ts
//   node scripts/contracts-openapi.mjs --check   exit 1 on lint errors or when either generated file is stale
// The bundle is the spec with every $ref (including contracts/schemas/*.json) resolved into components. Java copies it
// into the jar and serves it at GET /api/v1/openapi.json; other languages generate their SDKs from it.
import openapiTS, { astToString } from "openapi-typescript";
import { spawnSync } from "node:child_process";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const spec = join(root, "contracts", "openapi.yaml");
const bundle = join(root, "contracts", "openapi.bundled.json");
const paths = join(root, "packages", "core", "src", "generated", "api-paths.ts");
const check = process.argv.includes("--check");
const redocly = join(root, "node_modules", ".bin", "redocly");

function run(args) {
  const r = spawnSync(redocly, args, { cwd: root, encoding: "utf8" });
  return r;
}

// 1. lint: errors fail, warnings are shown
const lint = run(["lint", "contracts/openapi.yaml"]);
if (lint.status !== 0) {
  process.stdout.write(lint.stdout);
  process.stderr.write(lint.stderr);
  console.error("contracts/openapi.yaml has lint errors.");
  process.exit(1);
}
console.log("openapi lint: no errors");

// 2. bundle
const tmp = mkdtempSync(join(tmpdir(), "openapi-"));
const bundleTarget = check ? join(tmp, "openapi.bundled.json") : bundle;
const b = run(["bundle", "contracts/openapi.yaml", "-o", bundleTarget, "--ext", "json"]);
if (b.status !== 0) {
  process.stdout.write(b.stdout);
  process.stderr.write(b.stderr);
  console.error("Bundling failed.");
  process.exit(1);
}
const bundled = readFileSync(bundleTarget, "utf8");

// 3. TypeScript path types from the bundle
const ast = await openapiTS(pathToFileURL(bundleTarget));
const banner = "/* eslint-disable */\n// Generated by scripts/contracts-openapi.mjs from contracts/openapi.bundled.json. Do not edit; run `npm run contracts:openapi`.\n";
const text = banner + astToString(ast);

let stale = false;
if (check) {
  if (!existsSync(bundle) || readFileSync(bundle, "utf8") !== bundled) {
    console.error("contracts/openapi.bundled.json is stale. Run `npm run contracts:openapi`.");
    stale = true;
  }
  if (!existsSync(paths) || readFileSync(paths, "utf8") !== text) {
    console.error("packages/core/src/generated/api-paths.ts is stale. Run `npm run contracts:openapi`.");
    stale = true;
  }
} else {
  mkdirSync(dirname(paths), { recursive: true });
  writeFileSync(paths, text);
  console.log(`wrote ${bundle}\nwrote ${paths}`);
}
rmSync(tmp, { recursive: true, force: true });
if (stale) process.exit(1);
if (check) console.log("openapi bundle and path types are up to date");
